  "inlineSchema": "// Judoka Network - Database Schema\n// Judo belt verification and social network platform\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n  // directUrl = env(\"DIRECT_URL\")  // Temporarily disabled due to IPv6 requirement\n}\n\n// ============================================\n// USER & AUTHENTICATION\n// ============================================\n\nmodel User {\n  id          String    @id @default(cuid())\n  email       String    @unique\n  username    String    @unique\n  googleId    String?   @unique\n  avatar      String?\n  bio         String?\n  location    String?\n  currentBelt BeltColor\n  currentDan  Int? // For black belts (1-10)\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  // Relations\n  beltHistory           BeltProgression[]\n  givenVerifications    Verification[]    @relation(\"Verifier\")\n  receivedVerifications Verification[]    @relation(\"Verified\")\n  academyId             String?\n  academy               Academy?          @relation(fields: [academyId], references: [id])\n  achievements          UserAchievement[]\n\n  @@map(\"users\")\n}\n\n// ============================================\n// ACADEMY / DOJO\n// ============================================\n\nmodel Academy {\n  id         String   @id @default(cuid())\n  name       String\n  location   String\n  instructor String?\n  website    String?\n  createdAt  DateTime @default(now())\n  users      User[]\n\n  @@map(\"academies\")\n}\n\n// ============================================\n// BELT PROGRESSION SYSTEM\n// ============================================\n\nmodel BeltProgression {\n  id             String    @id @default(cuid())\n  userId         String\n  user           User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  beltColor      BeltColor\n  danRank        Int? // For black belts (1-10)\n  promotedAt     DateTime\n  promotedBy     String? // Instructor name\n  certificateUrl String?\n  notes          String?\n  createdAt      DateTime  @default(now())\n\n  verifications Verification[]\n\n  @@map(\"belt_progressions\")\n}\n\n// ============================================\n// COMMUNITY VERIFICATION\n// ============================================\n\nmodel Verification {\n  id                String             @id @default(cuid())\n  beltProgressionId String\n  beltProgression   BeltProgression    @relation(fields: [beltProgressionId], references: [id], onDelete: Cascade)\n  verifierId        String\n  verifier          User               @relation(\"Verifier\", fields: [verifierId], references: [id], onDelete: Cascade)\n  verifiedUserId    String\n  verifiedUser      User               @relation(\"Verified\", fields: [verifiedUserId], references: [id], onDelete: Cascade)\n  status            VerificationStatus\n  comment           String?\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n\n  @@map(\"verifications\")\n}\n\n// ============================================\n// ACHIEVEMENTS / GAMIFICATION\n// ============================================\n\nmodel Achievement {\n  id          String   @id @default(cuid())\n  name        String\n  description String\n  icon        String\n  criteria    String // JSON string for flexibility\n  createdAt   DateTime @default(now())\n\n  userAchievements UserAchievement[]\n\n  @@map(\"achievements\")\n}\n\nmodel UserAchievement {\n  id            String      @id @default(cuid())\n  userId        String\n  user          User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  achievementId String\n  achievement   Achievement @relation(fields: [achievementId], references: [id], onDelete: Cascade)\n  earnedAt      DateTime    @default(now())\n\n  @@unique([userId, achievementId])\n  @@map(\"user_achievements\")\n}\n\n// ============================================\n// ENUMS\n// ============================================\n\nenum BeltColor {\n  WHITE\n  YELLOW\n  ORANGE\n  GREEN\n  BLUE\n  BROWN\n  BLACK_1DAN\n  BLACK_2DAN\n  BLACK_3DAN\n  BLACK_4DAN\n  BLACK_5DAN\n  BLACK_6DAN\n  BLACK_7DAN\n  BLACK_8DAN\n  BLACK_9DAN\n  BLACK_10DAN\n}\n\nenum VerificationStatus {\n  PENDING\n  APPROVED\n  DISPUTED\n  REJECTED\n}\n",
